import json
from pathlib import Path

import numpy as np
import jax
import jax.numpy as jnp

ROOT = Path(__file__).resolve().parent


def basic_reduce(x: np.ndarray) -> jnp.ndarray:
    xj = jnp.asarray(x)
    return jnp.mean(xj, axis=1)


def map_square(x: np.ndarray) -> jnp.ndarray:
    xj = jnp.asarray(x)
    return jnp.square(xj)


def grad_logistic(data: dict) -> jnp.ndarray:
    x = jnp.asarray(data["x"])
    y = jnp.asarray(data["y"])
    w = jnp.asarray(data["w"])

    def loss_fn(w_local):
        logits = x @ w_local
        return jnp.mean(jnp.logaddexp(0.0, -y * logits))

    grad_w = jax.grad(loss_fn)(w)
    return grad_w


def scan_rnn(data: dict) -> jnp.ndarray:
    seq = jnp.asarray(data["seq"])
    init = jnp.asarray(data["init"])
    Wx = jnp.asarray(data["Wx"])
    Wh = jnp.asarray(data["Wh"])
    b = jnp.asarray(data["b"])

    def step(h, x_t):
        h_next = jnp.tanh(x_t @ Wx + h @ Wh + b)
        return h_next, h_next

    _, h_seq = jax.lax.scan(step, init, seq)
    return h_seq


def jit_mlp(data: dict) -> jnp.ndarray:
    X = jnp.asarray(data["X"])
    W1 = jnp.asarray(data["W1"])
    b1 = jnp.asarray(data["b1"])
    W2 = jnp.asarray(data["W2"])
    b2 = jnp.asarray(data["b2"])

    @jax.jit
    def mlp(x_local):
        h = jnp.maximum(0.0, x_local @ W1 + b1)
        return h @ W2 + b2

    return mlp(X)


TASKS = {
    "basic_reduce": "basic_reduce",
    "map_square": "map_square",
    "grad_logistic": "grad_logistic",
    "scan_rnn": "scan_rnn",
    "jit_mlp": "jit_mlp",
}


def load_input(path: Path):
    if path.suffix == ".npy":
        return np.load(path)
    if path.suffix == ".npz":
        return dict(np.load(path))
    raise ValueError(f"Unsupported input format: {path}")


def save_output(path: Path, arr: jnp.ndarray):
    path.parent.mkdir(parents=True, exist_ok=True)
    np.save(path, np.array(arr))


def main() -> None:
    problem_path = ROOT / "problem.json"
    tasks = json.loads(problem_path.read_text())

    for task in tasks:
        task_id = task["id"]
        input_path = ROOT / task["input"]
        output_path = ROOT / task["output"]

        data = load_input(input_path)

        if task_id == "basic_reduce":
            result = basic_reduce(data)
        elif task_id == "map_square":
            result = map_square(data)
        elif task_id == "grad_logistic":
            result = grad_logistic(data)
        elif task_id == "scan_rnn":
            result = scan_rnn(data)
        elif task_id == "jit_mlp":
            result = jit_mlp(data)
        else:
            raise ValueError(f"Unknown task id: {task_id}")

        save_output(output_path, result)


if __name__ == "__main__":
    main()
